from boto3 import client

class DynamoDBHelper:
    def __init__(self, table_name):
        self.dynamodb = client('dynamodb')
        self.table_name = table_name

    def create_item(self, item):
        normalized_item = self.normalize_item(item)
        response = self.dynamodb.put_item(
            TableName=self.table_name,
            Item=normalized_item
        )
        return response

    def get_item(self, key):
        response = self.dynamodb.get_item(
            TableName=self.table_name,
            Key=key
        )
        item = response.get('Item')
        if item:
            return self.denormalize_item(item)
        return None

    def normalize_item(self, item):
        normalized_item = {}
        for key, value in item.items():
            if isinstance(value, str):
                normalized_item[key] = {'S': value}
            elif isinstance(value, int):
                normalized_item[key] = {'N': str(value)}
            elif isinstance(value, list):
                normalized_item[key] = {'L': [{'S': str(v)} for v in value]}
        return normalized_item

    def denormalize_item(self, item):
        denormalized_item = {}
        for key, value in item.items():
            if 'S' in value:
                denormalized_item[key] = value['S']
            elif 'N' in value:
                denormalized_item[key] = int(value['N'])
            elif 'L' in value:
                denormalized_item[key] = [v['S'] for v in value['L']]
        return denormalized_item

import boto3

DYNAMODB_TABLE_NAME = 'MyDynamoDBTable'

def get_dynamodb_client():
    return boto3.client('dynamodb')

def create_table():
    dynamodb = get_dynamodb_client()
    try:
        dynamodb.create_table(
            TableName=DYNAMODB_TABLE_NAME,
            KeySchema=[
                {
                    'AttributeName': 'id',
                    'KeyType': 'HASH'  # Partition key
                }
            ],
            AttributeDefinitions=[
                {
                    'AttributeName': 'id',
                    'AttributeType': 'S'
                }
            ],
            ProvisionedThroughput={
                'ReadCapacityUnits': 5,
                'WriteCapacityUnits': 5
            }
        )
        print(f'Table {DYNAMODB_TABLE_NAME} created successfully.')
    except Exception as e:
        print(f'Error creating table: {e}')

def put_item(item):
    dynamodb = get_dynamodb_client()
    try:
        dynamodb.put_item(TableName=DYNAMODB_TABLE_NAME, Item=item)
        print('Item added successfully.')
    except Exception as e:
        print(f'Error adding item: {e}')

def get_item(key):
    dynamodb = get_dynamodb_client()
    try:
        response = dynamodb.get_item(TableName=DYNAMODB_TABLE_NAME, Key=key)
        item = response.get('Item')
        if item:
            print('Item retrieved successfully:', item)
        else:
            print('Item not found.')
    except Exception as e:
        print(f'Error retrieving item: {e}')

def delete_item(key):
    dynamodb = get_dynamodb_client()
    try:
        dynamodb.delete_item(TableName=DYNAMODB_TABLE_NAME, Key=key)
        print('Item deleted successfully.')
    except Exception as e:
        print(f'Error deleting item: {e}')

if __name__ == '__main__':
    create_table()

import boto3

def fetch_document(table_name, document_id):
    dynamodb = boto3.resource('dynamodb')
    table = dynamodb.Table(table_name)
    response = table.get_item(
        Key={'id': document_id}
    )
    return response.get('Item', None)

if __name__ == '__main__':
    table_name = 'Documents'
    document_id = '12345'
    document = fetch_document(table_name, document_id)
    if document:
        print(f'Document found: {document}')
    else:
        print('Document not found.')

import boto3

def upsert_document(table_name, item):
    dynamodb = boto3.resource('dynamodb')
    table = dynamodb.Table(table_name)
    response = table.put_item(Item=item)
    return response

